import { existsSync, readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { loadExport, repoFile } from '../src/testutil/load-export';
import {
	EXPECTED_MESSAGE_KEYS,
	EXTRA_MESSAGE_KEYS,
	PLURAL_MESSAGE_KEYS
} from './testdata/message-keys';

// The committed messages/{en,es,ru}.json (generated by scripts/import-strings.ts)
// are what Paraglide compiles. Every key must exist in all three locales.

type Locale = 'en' | 'es' | 'ru';
type ConvertStrings = (design: unknown, extra?: unknown) => Record<Locale, Record<string, unknown>>;

const LOCALES: Locale[] = ['en', 'es', 'ru'];
const designPath = repoFile('../design/design_handoff_asadorov_desktop/strings.json');
const extraPath = repoFile('src/lib/i18n/extra-strings.json');

function readJson(file: string): unknown {
	expect(existsSync(file), `got no file at ${file}, want one`).toBe(true);
	return JSON.parse(readFileSync(file, 'utf8'));
}

function readMessages(locale: Locale): Record<string, unknown> {
	const file = repoFile(`messages/${locale}.json`);
	expect(existsSync(file), `got no file at messages/${locale}.json, want one`).toBe(true);
	const all = JSON.parse(readFileSync(file, 'utf8')) as Record<string, unknown>;
	return Object.fromEntries(Object.entries(all).filter(([k]) => k !== '$schema'));
}

const keysOf = (locale: Locale) => Object.keys(readMessages(locale)).sort();

describe('committed messages', () => {
	for (const locale of ['es', 'ru'] as const) {
		it(`${locale}.json has exactly the same keys as en.json`, () => {
			const en = keysOf('en');
			const other = keysOf(locale);
			const onlyEn = en.filter((k) => !other.includes(k));
			const onlyOther = other.filter((k) => !en.includes(k));
			expect(onlyEn, `got keys missing from ${locale}: ${JSON.stringify(onlyEn)}`).toEqual([]);
			expect(onlyOther, `got keys only in ${locale}: ${JSON.stringify(onlyOther)}`).toEqual([]);
		});
	}

	for (const locale of LOCALES) {
		it(`${locale}.json holds every strings.json key`, () => {
			const got = keysOf(locale);
			const missing = EXPECTED_MESSAGE_KEYS.filter((k) => !got.includes(k));
			expect(missing, `got missing keys ${JSON.stringify(missing)}, want none`).toEqual([]);
		});

		it(`${locale}.json holds the extra-strings error-page keys`, () => {
			const got = keysOf(locale);
			const missing = EXTRA_MESSAGE_KEYS.filter((k) => !got.includes(k));
			expect(missing, `got missing keys ${JSON.stringify(missing)}, want none`).toEqual([]);
		});

		it(`${locale}.json has no empty message`, () => {
			const empty = Object.entries(readMessages(locale))
				.filter(([, v]) => v === '' || v === null)
				.map(([k]) => k);
			expect(empty, `got empty messages ${JSON.stringify(empty)}, want none`).toEqual([]);
		});
	}

	for (const key of PLURAL_MESSAGE_KEYS) {
		it(`${key} is a plural message in every locale`, () => {
			for (const locale of LOCALES) {
				const value = readMessages(locale)[key];
				expect(Array.isArray(value), `got ${locale} ${key} = ${JSON.stringify(value)}`).toBe(true);
			}
		});
	}
});

// Drift check, local only: the design bundle is outside this repo.
describe.skipIf(!existsSync(designPath))('committed messages vs the design strings.json', () => {
	for (const locale of LOCALES) {
		it(`${locale}.json matches what import-strings generates`, async () => {
			const convert = await loadExport<ConvertStrings>(
				'scripts/import-strings.ts',
				'convertStrings'
			);
			const want = convert(readJson(designPath), readJson(extraPath))[locale];
			const got = readMessages(locale);
			expect(Object.keys(got).sort(), 'got a different key set; rerun import-strings').toEqual(
				Object.keys(want).sort()
			);
			const drift = Object.keys(want).filter(
				(k) => JSON.stringify(got[k]) !== JSON.stringify(want[k])
			);
			expect(drift, `got stale keys ${JSON.stringify(drift)}; rerun import-strings`).toEqual([]);
		});
	}
});
